from pathlib import Path
import json
r=Path(__file__).resolve().parent;sections=[]
for cid,label in [('C06','중력 전환'),('C08','엔딩')]:
 src=f'../video-v2-prompt-r1/clips/{cid}.mp4';out=f'clips/{cid}.mp4'
 if not (r/out).exists():continue
 sections.append(f'''<section data-pair><h2>{cid} · {label}</h2><div class="grid"><article><h3>스크린 안쪽만 수정</h3><video controls playsinline preload="metadata" src="{out}"></video><a href="{out}" download>수정 영상 다운로드</a></article><article><h3>수정 전 기준 영상</h3><video controls playsinline preload="metadata" muted src="{src}"></video><a href="{src}">기준 영상 열기</a></article></div><div class="controls"><button data-play>두 영상 함께 재생</button><button data-pause>일시 정지</button><button data-reset>처음으로</button></div></section>''')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>스크린 내부 일렁임 · 국소 수정</title><style>body{margin:0;background:#111817;color:#e8efea;font:15px/1.65 system-ui}main{max-width:1600px;margin:auto;padding:32px 24px}h1{font-size:28px}h2{font-size:20px}h3{font-size:14px;color:#aac0b4;font-weight:400}section{margin:30px 0;border-top:1px solid #3c4e44;padding-top:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}video{width:100%;display:block;background:#000}a{color:#b8d8c7;display:inline-block;margin-top:10px}button{font:inherit;cursor:pointer;color:#d8e8df;background:#233a2d;border:1px solid #526b5b;border-radius:4px;padding:8px 14px}.controls{display:flex;gap:8px;margin-top:18px;flex-wrap:wrap}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style><main><h1>스크린 안쪽 무늬만 미세하게 일렁이도록 수정</h1><p>과한 연기를 넣기 전 6·8번을 기준으로 작업했습니다. 원래 스크린 무늬에만 작은 움직임을 적용했으며, 랜딩페이지에는 아직 교체하지 않았습니다.</p>'''+''.join(sections)+'''</main><script>for(const pair of document.querySelectorAll('[data-pair]')){const videos=[...pair.querySelectorAll('video')];pair.querySelector('[data-play]').onclick=async()=>{videos[1].currentTime=videos[0].currentTime;try{await Promise.all(videos.map(v=>v.play()))}catch{}};pair.querySelector('[data-pause]').onclick=()=>videos.forEach(v=>v.pause());pair.querySelector('[data-reset]').onclick=()=>videos.forEach(v=>{v.pause();v.currentTime=0})}</script></html>'''
(r/'review.html').write_text(page);print('Review ready:',len(sections),'clips')
